CREATE OR REPLACE FUNCTION public.add_card_label(_card_id uuid,_name text,_color text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE bid uuid; lid uuid; BEGIN IF NOT public.can_access_card(_card_id) THEN RAISE EXCEPTION 'Card unavailable'; END IF; IF _color NOT IN ('green','yellow','orange','red','purple','blue') THEN RAISE EXCEPTION 'Invalid label color'; END IF; SELECT board_id INTO bid FROM public.cards WHERE id=_card_id; INSERT INTO public.labels(board_id,name,color) VALUES(bid,_name,_color) RETURNING id INTO lid; INSERT INTO public.card_labels(card_id,label_id) VALUES(_card_id,lid); RETURN lid; END $$;
CREATE OR REPLACE FUNCTION public.protect_label_board() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.board_id<>OLD.board_id THEN RAISE EXCEPTION 'Label board cannot change'; END IF; RETURN NEW; END $$;
CREATE TRIGGER label_board_immutable BEFORE UPDATE ON public.labels FOR EACH ROW EXECUTE FUNCTION public.protect_label_board();
CREATE OR REPLACE FUNCTION public.unique_card_placement_id() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_TABLE_NAME='cards' THEN IF EXISTS(SELECT 1 FROM public.card_mirrors WHERE id=NEW.id) THEN RAISE EXCEPTION 'Card placement ID already exists'; END IF; ELSE IF EXISTS(SELECT 1 FROM public.cards WHERE id=NEW.id) THEN RAISE EXCEPTION 'Card placement ID already exists'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER card_placement_id_unique BEFORE INSERT ON public.cards FOR EACH ROW EXECUTE FUNCTION public.unique_card_placement_id();
CREATE TRIGGER mirror_placement_id_unique BEFORE INSERT ON public.card_mirrors FOR EACH ROW EXECUTE FUNCTION public.unique_card_placement_id();
REVOKE ALL ON FUNCTION public.add_card_label(uuid,text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.add_card_label(uuid,text,text) TO authenticated,service_role;